# Let's define the graph with 13 vertices (0-12)
# One clique of size 4: {0, 1, 2, 3}
# The other 9 vertices are isolated: {4, 5, 6, 7, 8, 9, 10, 11, 12}

edges = []
clique = [0, 1, 2, 3]
for i in range(len(clique)):
    for j in range(i + 1, len(clique)):
        edges.append((clique[i], clique[j]))

print(edges)
